SELECT country, CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, city, AVG(rating) AS avg_rating, MIN(rating) AS min_rating, SUM(rating) AS total_rating FROM suppliers WHERE (country = 'TH' AND city = 'New York') OR rating BETWEEN 2.0 AND 3.8 GROUP BY country, CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END, city ORDER BY avg_rating DESC, country
